import type { Service, ServiceResponse, StockReportSource } from "./types";
import { error } from "./reservation";
import { decodeSnapshotStock, isRecord, isUnits } from "./validation";

function parseCommand(raw: unknown): { op: "lowStock"; belowUnits: number } | undefined {
  if (!isRecord(raw) || raw.op !== "lowStock" || !isUnits(raw.belowUnits)) return undefined;
  return { op: "lowStock", belowUnits: raw.belowUnits };
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        const snapshot = await source.readSnapshot();
        if (!Array.isArray(snapshot)) return error(500, "storage_unavailable");

        const seenSkus = new Set<string>();
        const items: Array<{ sku: string; availableUnits: number }> = [];
        for (const row of snapshot) {
          const stock = decodeSnapshotStock(row);
          if (!stock || seenSkus.has(stock.sku)) return error(500, "storage_unavailable");
          seenSkus.add(stock.sku);

          const availableUnits = stock.totalUnits - stock.reservedUnits;
          if (availableUnits < command.belowUnits) items.push({ sku: stock.sku, availableUnits });
        }

        items.sort((left, right) => left.sku < right.sku ? -1 : left.sku > right.sku ? 1 : 0);
        return { status: 200, body: { items } };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

